ists</a>.</div></div><div class="col-md-6" id="checklist-timing-field"><label class="form-label">Momento de preenchimento</label><select class="form-select" name="checklist_timing"><option value="start" <?=($edit['checklist_timing']??'start')==='start'?'selected':''?>>No início da operação</option><option value="end" <?=($edit['checklist_timing']??'')==='end'?'selected':''?>>No fim da operação</option><option value="first" <?=($edit['checklist_timing']??'')==='first'?'selected':''?>>Na primeira vez do colaborador nesta operação da OF</option></select></div><div class="col-12"><label class="form-label">Observações</label><textarea class="form-control" name="notes"><?=h((string)($edit['notes']??''))?></textarea></div><div class="col-12"><button class="btn btn-primary">Guardar</button> <a class="btn btn-outline-secondary" href="erp_operations.php">Cancelar</a></div></form></div></div><?php endif;?></div>
<script>
document.addEventListener('DOMContentLoaded', function () {
    var editor = document.getElementById('work-instruction-editor');
    var input = document.getElementById('work-instruction-html');
    var checklist = document.getElementById('operation-checklist');
    var timing = document.getElementById('checklist-timing-field');
    if (checklist && timing) {
        var toggleTiming = function () { timing.classList.toggle('d-none', checklist.value === '0'); };
        checklist.addEventListener('change', toggleTiming); toggleTiming();
    }
    if (!editor || !input) return;
    document.querySelectorAll('[data-editor-command]').forEach(function (button) {
        button.addEventListener('click', function () {
            editor.focus();
            document.execCommand(button.dataset.editorCommand, false, null);
            input.value = editor.innerHTML;
        });
    });
    editor.addEventListener('input', function () { input.value = editor.innerHTML; });
    editor.closest('form').addEventListener('submit', function () { input.value = editor.innerHTML; });
});
</script>
